{"content": "import { createReadStream, writeFileSync } from 'node:fs';
import { createZstdDecompress } from 'node:zlib';
import { once } from 'node:events';

const src = process.argv[2];
const out = process.argv[3];

const chunks = [];
const stream = createReadStream(src).pipe(createZstdDecompress());
stream.on('data', (c) => chunks.push(c));
stream.on('error', (e) => { console.error('ERR', e); process.exit(1); });
await once(stream, 'end');
const text = Buffer.concat(chunks).toString('utf8');
writeFileSync(out, text);
const lines = text.split('\n').filter(Boolean);
console.log('decompressed bytes:', text.length, 'lines:', lines.length);
const types = new Map();
for (const line of lines) {
  try {
    const ev = JSON.parse(line);
    const t = ev.type ?? ev.kind ?? Object.keys(ev)[0];
    types.set(t, (types.get(t) ?? 0) + 1);
  } catch {
    types.set('<unparsable>', (types.get('<unparsable>') ?? 0) + 1);
  }
}
console.log([...types.entries()].map(([k, v]) => `${k}: ${v}`).join('\n'));
