{"content": "import { readFileSync, writeFileSync } from 'node:fs';
import { zstdDecompressSync, constants } from 'node:zlib';

const ZSTD_MAGIC = 0xFD2FB528;

function scanZstdFrames(buffer) {
  const frames = [];
  let offset = 0;
  while (offset < buffer.length) {
    const start = offset;
    if (buffer.length - offset < 4) return { frames, tornStart: start };
    if (buffer.readUInt32LE(offset) !== ZSTD_MAGIC) {
      throw new Error(`invalid frame magic at byte ${offset}`);
    }
    offset += 4;
    if (offset === buffer.length) return { frames, tornStart: start };
    const descriptor = buffer.readUInt8(offset);
    offset += 1;
    if ((descriptor & 0x18) !== 0) throw new Error(`reserved frame-header bit at byte ${offset - 1}`);
    const contentSizeFlag = descriptor >>> 6;
    const singleSegment = (descriptor & 0x20) !== 0;
    const checksum = (descriptor & 0x04) !== 0;
    const dictionaryFlag = descriptor & 0x03;
    const dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag;
    const contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : 1 << contentSizeFlag;
    const remainingHeaderBytes = (singleSegment ? 0 : 1) + dictionaryBytes + contentSizeBytes;
    if (buffer.length - offset < remainingHeaderBytes) return { frames, tornStart: start };
    offset += remainingHeaderBytes;
    for (;;) {
      if (buffer.length - offset < 3) return { frames, tornStart: start };
      const blockHeader = buffer.readUIntLE(offset, 3);
      offset += 3;
      const lastBlock = (blockHeader & 1) !== 0;
      const blockType = (blockHeader >>> 1) & 0x03;
      const blockSize = blockHeader >>> 3;
      if (blockType === 0x03) throw new Error(`reserved block type at byte ${offset - 3}`);
      const payloadBytes = blockType === 0x01 ? 1 : blockSize;
      if (buffer.length - offset < payloadBytes) return { frames, tornStart: start };
      offset += payloadBytes;
      if (lastBlock) break;
    }
    if (checksum) {
      if (buffer.length - offset < 4) return { frames, tornStart: start };
      offset += 4;
    }
    frames.push({ start, end: offset });
  }
  return { frames };
}

const src = process.argv[2];
const out = process.argv[3];
const buf = readFileSync(src);
const { frames, tornStart } = scanZstdFrames(buf);
const parts = [];
for (const f of frames) {
  parts.push(zstdDecompressSync(buf.subarray(f.start, f.end)));
}
let tornPlain = '';
if (tornStart !== undefined) {
  try {
    tornPlain = zstdDecompressSync(buf.subarray(tornStart), { finishFlush: constants.ZSTD_e_flush }).toString('utf8');
  } catch (e) {
    console.error('torn frame not recoverable:', e.message);
  }
}
const text = Buffer.concat(parts).toString('utf8') + tornPlain;
writeFileSync(out, text);
const lines = text.split('\n').filter(Boolean);
console.log('frames:', frames.length, 'tornStart:', tornStart ?? 'none');
console.log('decompressed bytes:', text.length, 'lines:', lines.length);
const types = new Map();
for (const line of lines) {
  try {
    const ev = JSON.parse(line);
    const t = ev.type ?? ev.kind ?? Object.keys(ev)[0];
    types.set(t, (types.get(t) ?? 0) + 1);
  } catch {
    types.set('<unparsable>', (types.get('<unparsable>') ?? 0) + 1);
  }
}
console.log([...types.entries()].map(([k, v]) => `${k}: ${v}`).join('\n'));
