const lines = readFileSync(process.argv[2], 'utf8').split('\n').filter(Boolean);
const events = lines.map((l) => JSON.parse(l));
const out = process.argv[3];

const wanted = ['system/message', 'request/header', 'request/context', 'command/run', 'command/done', 'session'];
for (const ev of events) {
  if (!wanted.includes(ev.type)) continue;
  const name = ev.type.replaceAll('/', '_');
  writeFileSync(`${out}\\ev-${name}.json`, JSON.stringify(ev, null, 2));
  console.log(`== ${ev.type} :: ${JSON.stringify(ev).length} chars`);
}

for (const ev of events) {
  if (ev.type === 'system/message') {
    const text = typeof ev.message === 'object' ? (ev.message?.content ?? JSON.stringify(ev.message)) : ev.message;
    const rendered = typeof text === 'string' ? text : JSON.stringify(text);
    console.log('system text length:', rendered.length);
  }
}
